export const BRAND_KEYS = Object.keys(BRANDS);
export const brandSvg = (k, size = 22) => { const b = BRANDS[k]; return b ? `<svg viewBox="0 0 24 24" width="${size}" height="${size}" fill="currentColor" aria-hidden="true" focusable="false"><path d="${b.d}"/></svg>` : ""; };
/* Pick the brand from a web address, so pasting a link picks the right logo and name. */
const HOSTS = [[/(^|\.)instagram\.com$/, "instagram"], [/(^|\.)(youtube\.com|youtu\.be)$/, "youtube"], [/(^|\.)linkedin\.com$/, "linkedin"], [/(^|\.)(x\.com|twitter\.com)$/, "x"], [/(^|\.)(facebook\.com|fb\.com|fb\.me)$/, "facebook"], [/(^|\.)threads\.(net|com)$/, "threads"], [/(^|\.)tiktok\.com$/, "tiktok"], [/(^|\.)behance\.net$/, "behance"], [/(^|\.)dribbble\.com$/, "dribbble"], [/(^|\.)github\.com$/, "github"], [/(^|\.)figma\.com$/, "figma"], [/(^|\.)pinterest\.[a-z.]+$/, "pinterest"], [/(^|\.)reddit\.com$/, "reddit"], [/(^|\.)spotify\.com$/, "spotify"], [/^music\.apple\.com$/, "applemusic"], [/(^|\.)soundcloud\.com$/, "soundcloud"], [/(^|\.)medium\.com$/, "medium"], [/(^|\.)substack\.com$/, "substack"], [/(^|\.)patreon\.com$/, "patreon"], [/(^|\.)ko-fi\.com$/, "kofi"], [/(^|\.)buymeacoffee\.com$/, "buymeacoffee"], [/(^|\.)notion\.(so|site)$/, "notion"], [/(^|\.)gumroad\.com$/, "gumroad"], [/(^|\.)(wa\.me|whatsapp\.com)$/, "whatsapp"], [/(^|\.)(t\.me|telegram\.org)$/, "telegram"], [/(^|\.)signal\.(me|org)$/, "signal"], [/(^|\.)discord\.(gg|com)$/, "discord"], [/(^|\.)twitch\.tv$/, "twitch"], [/(^|\.)snapchat\.com$/, "snapchat"], [/(^|\.)vimeo\.com$/, "vimeo"], [/(^|\.)bsky\.app$/, "bluesky"], [/(^|\.)calendly\.com$/, "calendly"], [/(^|\.)unsplash\.com$/, "unsplash"], [/(^|\.)producthunt\.com$/, "producthunt"], [/(^|\.)codepen\.io$/, "codepen"], [/(^|\.)stackoverflow\.com$/, "stackoverflow"], [/(^|\.)canva\.com$/, "canva"], [/(^|\.)etsy\.com$/, "etsy"], [/(^|\.)slack\.com$/, "slack"], [/(^|\.)tumblr\.com$/, "tumblr"], [/(^|\.)flickr\.com$/, "flickr"], [/(^|\.)artstation\.com$/, "artstation"], [/(^|\.)upwork\.com$/, "upwork"], [/(^|\.)fiverr\.com$/, "fiverr"], [/(^|\.)paypal\.(com|me)$/, "paypal"]];
export function brandOfUrl(url) { try { const h = new URL(/^[a-z]+:/i.test(url) ? url : "https://" + url).hostname.replace(/^www\./, ""); for (const [re, k] of HOSTS) if (re.test(h)) return k; } catch {} return ""; }
